-- =============================================================================
-- Migration V11: Create Quotation tables (khung tối thiểu cho Module 4 - Survey)
-- Tables: quotations, quotation_items
-- So với schema leader: thêm 3 cột cờ đồ đạc ở quotation_items, DEFAULT 0 cho các cột tiền
-- (bản nháp do khảo sát tạo chưa có giá), status dùng varchar + Java enum như V8.
-- =============================================================================

-- 1. Bảng quotations (mỗi lần khảo sát / khảo sát lại sinh 1 version mới)
CREATE TABLE IF NOT EXISTS "quotations" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "version" int NOT NULL DEFAULT 1,
  "amount" decimal(12,2) NOT NULL DEFAULT 0,
  "discount_amount" decimal(12,2) NOT NULL DEFAULT 0,
  "final_amount" decimal(12,2) NOT NULL DEFAULT 0,
  "status" varchar(30) NOT NULL DEFAULT 'DRAFT',
  "note" text,
  "valid_until" timestamp,
  "created_by" bigint,
  "accepted_at" timestamp,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_quotations_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_quotations_created_by FOREIGN KEY ("created_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_quotations_amounts CHECK (amount >= 0 AND discount_amount >= 0 AND final_amount >= 0),
  CONSTRAINT chk_quotations_version CHECK (version > 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_quotations_booking_version ON "quotations" ("booking_id", "version");
-- Mỗi booking tối đa 1 bản nháp: bản DRAFT luôn thuộc về lần khảo sát đang chạy
CREATE UNIQUE INDEX IF NOT EXISTS uq_quotations_one_draft_per_booking ON "quotations" ("booking_id") WHERE status = 'DRAFT';
CREATE INDEX IF NOT EXISTS idx_quotations_booking_id ON "quotations" ("booking_id");

-- 2. Bảng quotation_items (đồ đạc thực tế sau khảo sát + đơn giá khi Quotation tính)
CREATE TABLE IF NOT EXISTS "quotation_items" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "quotation_id" int NOT NULL,
  "booking_item_id" int,
  "item_name" varchar(255) NOT NULL,
  "quantity" int NOT NULL,
  "unit" varchar(50),
  "unit_price" decimal(12,2) NOT NULL DEFAULT 0,
  "line_amount" decimal(12,2) NOT NULL DEFAULT 0,
  "estimated_volume_m3" decimal(10,2),
  "is_fragile" boolean NOT NULL DEFAULT false,
  "packing_required" boolean NOT NULL DEFAULT false,
  "disassembly_required" boolean NOT NULL DEFAULT false,
  "note" text,
  CONSTRAINT fk_quotation_items_quotation FOREIGN KEY ("quotation_id") REFERENCES "quotations" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_quotation_items_booking_item FOREIGN KEY ("booking_item_id") REFERENCES "booking_items" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_quotation_items_quantity CHECK (quantity > 0),
  CONSTRAINT chk_quotation_items_amounts CHECK (unit_price >= 0 AND line_amount >= 0),
  CONSTRAINT chk_quotation_items_volume CHECK (estimated_volume_m3 IS NULL OR estimated_volume_m3 >= 0)
);

CREATE INDEX IF NOT EXISTS idx_quotation_items_quotation_id ON "quotation_items" ("quotation_id");
